from datetime import datetime, timedelta

SLOT_DURATION_MINUTES = 60
DAY_START_HOUR = 0
DAY_START_MINUTE = 0
DAY_END_HOUR = 23
DAY_END_MINUTE = 59

class CalendarUtil:
    def __init__(self):
        self._events = []

    @property
    def events(self):
        """Return a copy of the events list to encapsulate the collection."""
        return list(self._events)

    def add_event(self, event):
        self._events.append(event)

    def remove_event(self, event):
        if event in self._events:
            self._events.remove(event)

    def get_events(self, date):
        return [event for event in self._events if event['date'].date() == date.date()]

    def is_available(self, start_time, end_time):
        return not any(start_time < event['end_time'] and end_time > event['start_time'] for event in self._events)

    def get_available_slots(self, date):
        available_slots = []
        start_time = datetime(date.year, date.month, date.day, DAY_START_HOUR, DAY_START_MINUTE)
        end_time = datetime(date.year, date.month, date.day, DAY_END_HOUR, DAY_END_MINUTE)

        slot_end_time = start_time + timedelta(minutes=SLOT_DURATION_MINUTES)
        while start_time < end_time:
            if self.is_available(start_time, slot_end_time):
                available_slots.append((start_time, slot_end_time))
            start_time = slot_end_time
            slot_end_time = start_time + timedelta(minutes=SLOT_DURATION_MINUTES)

        return available_slots

    def get_upcoming_events(self, num_events):
        return [event for event in self._events if event['start_time'] >= datetime.now()][:num_events]
